def generate_preserve_grid_fixed(input_grid):
    sep_rows = {4, 9, 14, 19}
    sep_cols = {4, 9, 14, 19}

    output = []
    for rr in range(24):
        row = []
        for cc in range(24):
            if rr in sep_rows or cc in sep_cols:
                row.append(5)
            else:
                gh = rr // 5
                gc = cc // 5

                # Find max color
                max_c = 0
                for r in range(4):
                    for c in range(4):
                        v = input_grid[gh*5+r][gc*5+c]
                        if 0 < v < 5:
                            max_c = max(max_c, v)

                # Calculate offset within the 4x4 data area
                r_offset = rr - gh*5
                c_offset = cc - gc*5

                # Get val from CORRESPONDING position in input
                val = input_grid[gh*5 + r_offset][gc*5 + c_offset]

                if 0 < val < 5:
                    row.append(max_c)
                else:
                    row.append(0)
        output.append(row)
    return output

output_fixed = generate_preserve_grid_fixed(input_grid)

